INSERT INTO "LocaleStringResource" ("LanguageId","ResourceName","ResourceValue") SELECT 7,'admin.catalog.manufacturers.gpsr.information','<p>Le règlement général relatif à la sécurité des produits (GPSR) est une loi de l''Union européenne (UE) entrée en vigueur en décembre 2024. Le GPSR encadre la publicité et la vente de produits de consommation dans l''Union européenne.</p><p>Si vous êtes situé dans l''UE, vous devez indiquer le nom du fabricant, son adresse postale ainsi que son adresse e-mail ou toute autre coordonnée électronique.</p><p>Si le fabricant n''est pas établi dans l''Union européenne, indiquez la personne responsable dans l''UE et ses coordonnées. La personne responsable dans l''UE est une personne ou une entité établie dans l''Union européenne que le vendeur désigne comme interlocuteur auprès des autorités de l''UE.</p>' WHERE NOT EXISTS (SELECT 1 FROM "LocaleStringResource" WHERE "LanguageId"=7 AND lower("ResourceName")=lower('admin.catalog.manufacturers.gpsr.information'));
