INSERT INTO "LocaleStringResource" ("LanguageId","ResourceName","ResourceValue") SELECT 7,'plugins.widgets.googleanalytics.instructions','<p>Google Analytics est un outil gratuit de statistiques de sites web proposé par Google. Il suit les statistiques des visiteurs et des conversions de commerce électronique sur votre site.<br /><br />Suivez les étapes ci-dessous pour activer l''intégration de Google Analytics :<br /><ul><li><a href="http://www.google.com/analytics/" target="_blank">Créez un compte Google Analytics</a> et suivez l''assistant pour ajouter votre site web</li><li>Copiez l''<b>ID DE MESURE</b> dans le champ <b>ID</b> ci-dessous</li><li>Dans Google Analytics, cliquez sur <b>Secrets de l''API Measurement Protocol</b> sous <b>Événements</b></li><li>Cliquez sur le bouton <b>Créer</b> et suivez les instructions pour créer un nouveau secret d''API</li><li>Copiez le secret d''API dans le champ <b>Secret d''API</b> ci-dessous</li><li>Cliquez sur le bouton « Enregistrer » ci-dessous et Google Analytics sera intégré à votre boutique</li></ul><br /></p>' WHERE NOT EXISTS (SELECT 1 FROM "LocaleStringResource" WHERE "LanguageId"=7 AND lower("ResourceName")=lower('plugins.widgets.googleanalytics.instructions'));
